SELECT r.job_id, r.slack_ts, r.observed_state, r.observed_at, r.observation_uncertain, r.outcome, r.phase, r.revision, r.sent_revision, r.state, r.attempts, r.next_attempt_at, r.refresh_at, r.rate_limited_until, r.first_sent_at, r.last_sent_at, r.reason, r.updated_at, r.mode FROM request_status r WHERE $criteria.CompositeIn("r", $Unsafe.ProjectCurrentStatusParentKeys($CurrentWriter))